double fa = f(a);
double fb = f(b);
double c = (a + b) / 2.0;
double fc = f(c);
double S = (b - a) / 6.0 * (fa + 4.0*fc + fb);
double Sl = (c - a) / 6.0 * (fa + 4.0*f((a + c) / 2.0) + f(c));
double Sr = (b - c) / 6.0 * (f(c) + 4.0*f((c + b) / 2.0) + fb);
double S2 = Sl + Sr;
double err = std::abs(S2 - S);
if (err <= 15.0 * precision / 16.0)
    return S2 + (S2 - S) / 15.0;
return adaptive_simpson(f, a, c, precision / 2.0) + adaptive_simpson(f, c, b, precision / 2.0);

